// --- Physics (movement + wall/paddle/brick bounces) ------------------------

// Bounces the ball off every brick it currently overlaps (issue #1).
//
// The whole step is sub-stepped in `step()`, so this function only ever has to
// deal with a *small* overlap (a couple of pixels at most). That small-overlap
// regime is exactly what makes the classic per-face rule reliable here:
//
//   * the axis holding the *smaller* penetration is the face that was hit -
//     flip `vx` on a side hit, `vy` on a top/bottom hit, and leave the other
//     component untouched;
//   * equal penetrations mean a diagonal (corner) hit - flip both;
//   * the ball is pushed back out of the brick so it never re-collides on the
//     next sub-step (no sticky bounce);
//   * when several bricks overlap at the same time (a seam: the 8 px gap is
//     narrower than the 14 px ball), the resolution is consolidated so the
//     velocity component is flipped **exactly once** - flipping twice would
//     cancel out and the ball would keep plowing straight through.
//
// Destroys the bricks it hits and awards score (combo included). Returns true
// if at least one brick was broken.
export function resolveBallCollision(ball, bricks, state) {
  const hits = bricks.filter((b) => b.alive && collides(ball, b));
  if (hits.length === 0) return false;

  for (const b of hits) {
    b.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(b, state.combo);
  }

  const axis = pickAxis(ball, hits);

  // Push out along the resolved face and point the ball back the way it came.
  // Using the min/max across all hits clears the whole seam in one go.
  if (axis === 'x' || axis === 'both') {
    if (ball.vx > 0) {
      // came from the left → bounce it back to the left
      ball.x = Math.min(...hits.map((b) => b.x)) - ball.r;
      ball.vx = -Math.abs(ball.vx);
    } else {
      // came from the right → bounce it back to the right
      ball.x = Math.max(...hits.map((b) => b.x + b.w)) + ball.r;
      ball.vx = Math.abs(ball.vx);
    }
  }

  if (axis === 'y' || axis === 'both') {
    if (ball.vy > 0) {
      // came from above → bounce it back up
      ball.y = Math.min(...hits.map((b) => b.y)) - ball.r;
      ball.vy = -Math.abs(ball.vy);
    } else {
      // came from below → bounce it back down
      ball.y = Math.max(...hits.map((b) => b.y + b.h)) + ball.r;
      ball.vy = Math.abs(ball.vy);
    }
  }

  return true;
}

// Picks the single face to resolve among all overlapping bricks: the axis of
// the shallowest (minimum) penetration overall. Returns 'x', 'y' or 'both'
// (the latter when penetrations are equal → a corner/diagonal hit).
function pickAxis(ball, hits) {
  let axis = null;
  let best = Infinity;
  for (const b of hits) {
    const ox =
      Math.min(ball.x + ball.r, b.x + b.w) - Math.max(ball.x - ball.r, b.x);
    const oy =
      Math.min(ball.y + ball.r, b.y + b.h) - Math.max(ball.y - ball.r, b.y);
    const p = Math.min(ox, oy);
    if (p < best) {
      best = p;
      if (ox < oy) axis = 'x';
      else if (oy < ox) axis = 'y';
      else axis = 'both';
    }
  }
  return axis;
}

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks.
//
// The move is split into small sub-steps (at most 2 px each). This kills two
// birds at once (issue #1):
//
//   * tunnelling: the ball is 14 px across and a brick face is ~20 px thick,
//     but at high speed a full 50 ms frame can jump >35 px and skip a brick
//     entirely - a 2 px sub-step can never leap over it;
//   * face detection: each sub-step only ever produces a small overlap, which
//     is exactly the regime where the per-face penetration rule is accurate.
//
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  const distance = Math.hypot(ball.vx, ball.vy) * dt;
  const steps = Math.max(1, Math.ceil(distance / 2));
  const h = dt / steps;

  for (let i = 0; i < steps; i++) {
    ball.x += ball.vx * h;
    ball.y += ball.vy * h;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0; // touching the paddle resets the combo
    }

    // Bricks: deflect + destroy + score.
    resolveBallCollision(ball, state.bricks, state);

    // Exit through the bottom: ball lost
    if (ball.y - ball.r > HEIGHT) {
      return true;
    }
  }
  return false;
}

